 {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    -- Can’t cast on living targets\n    if target:isAlive() then\n        return xi.msg.basic.MAGIC_CANNOT_BE_CAST\n    end\n\n    -- Only PCs should ever be blocked by the Raise/Tractor menu state\n    if target:isPC() and target:hasRaiseTractorMenu() then\n        return xi.msg.basic.MAGIC_CANNOT_BE_CAST\n    end\n\n    -- Non-PC targets must be explicitly raisable (behavior bit)\n    if\n        not target:isPC() and\n        bit.band(target:getBehavior(), xi.behavior.RAISABLE) == 0\n    then\n        return xi.msg.basic.MAGIC_CANNOT_BE_CAST\n    end\n\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    if target:isPC() then\n        target:sendRaise(1)\n    end\n\n    spell:setMsg(xi.msg.basic.MAGIC_CASTS_ON)\n    return 1\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/raise_ii.lua"]={["Path"]="scripts/actions/spells/white/raise_ii.lua",["SHA256"]="1ae8ce3c7048775006e40bcad49a3944e51a50e30a71896df721187050936059",["Text"]="-----------------------------------\n-- Spell: Raise II\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    -- Can't cast on living targets\n    if target:isAlive() then\n        return xi.msg.basic.MAGIC_CANNOT_BE_CAST\n    end\n\n    -- Only PCs should ever be blocked by the Raise/Tractor menu state\n    if target:isPC() and target:hasRaiseTractorMenu() then\n        return xi.msg.basic.MAGIC_CANNOT_BE_CAST\n    end\n\n    -- Non-PC targets must be explicitly raisable (behavior bit)\n    if\n        not target:isPC() and\n        bit.band(target:getBehavior(), xi.behavior.RAISABLE) == 0\n    then\n        return xi.msg.basic.MAGIC_CANNOT_BE_CAST\n    end\n\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    if target:isPC() then\n        target:sendRaise(2)\n    end\n\n    spell:setMsg(xi.msg.basic.MAGIC_CASTS_ON)\n    return 2\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/raise_iii.lua"]={["Path"]="scripts/actions/spells/white/raise_iii.lua",["SHA256"]="b29f5510505b9c7cd1824580df1e0cc422e90eede7bb5c5aa6fe0ee22d35395d",["Text"]="-----------------------------------\n-- Spell: Raise III\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    -- Can't cast on living targets\n    if target:isAlive() then\n        return xi.msg.basic.MAGIC_CANNOT_BE_CAST\n    end\n\n    -- Only PCs should ever be blocked by the Raise/Tractor menu state\n    if target:isPC() and target:hasRaiseTractorMenu() then\n        return xi.msg.basic.MAGIC_CANNOT_BE_CAST\n    end\n\n    -- Non-PC targets must be explicitly raisable (behavior bit)\n    if\n        not target:isPC() and\n        bit.band(target:getBehavior(), xi.behavior.RAISABLE) == 0\n    then\n        return xi.msg.basic.MAGIC_CANNOT_BE_CAST\n    end\n\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    if target:isPC() then\n        target:sendRaise(3)\n    end\n\n    spell:setMsg(xi.msg.basic.MAGIC_CASTS_ON)\n    return 3\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/recall-jugner.lua"]={["Path"]="scripts/actions/spells/white/recall-jugner.lua",["SHA256"]="fbb14ea9002ff2f2a49b8f2aa4e97ac66f5545a700ffe565de66e0508940c00e",["Text"]="-----------------------------------\n-- Spell: Recall-Jugner\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useTeleportSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/recall-meriph.lua"]={["Path"]="scripts/actions/spells/white/recall-meriph.lua",["SHA256"]="db8960b1f9f96ba841dcc6